package com.mahesh.empleave.common.exception;import com.mahesh.empleave.common.response.*;import org.springframework.http.*;import org.springframework.security.access.*;import org.springframework.security.core.*;import org.springframework.web.bind.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.*;import java.time.*;import java.util.*;@RestControllerAdvice public class ApiExceptionHandler{private ApiError body(HttpStatus s,String m,Map<String,String> f){return new ApiError(Instant.now(),s.value(),s.getReasonPhrase(),m,f);}@ExceptionHandler(NoSuchElementException.class) ResponseEntity<ApiError> missing(NoSuchElementException e){return ResponseEntity.status(404).body(body(HttpStatus.NOT_FOUND,"Resource not found",Map.of()));}@ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class}) ResponseEntity<ApiError> business(RuntimeException e){return ResponseEntity.badRequest().body(body(HttpStatus.BAD_REQUEST,e.getMessage(),Map.of()));}@ExceptionHandler({SecurityException.class,AccessDeniedException.class}) ResponseEntity<ApiError> forbidden(Exception e){return ResponseEntity.status(403).body(body(HttpStatus.FORBIDDEN,"Access denied",Map.of()));}@ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiError> invalid(MethodArgumentNotValidException e){var f=new HashMap<String,String>();e.getBindingResult().getFieldErrors().forEach(x->f.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(body(HttpStatus.BAD_REQUEST,"Validation failed",f));}@ExceptionHandler(ResponseStatusException.class) ResponseEntity<ApiError> status(ResponseStatusException e){var s=HttpStatus.valueOf(e.getStatusCode().value());return ResponseEntity.status(s).body(body(s,e.getReason(),Map.of()));}@ExceptionHandler(AuthenticationException.class) ResponseEntity<ApiError> auth(AuthenticationException e){return ResponseEntity.status(401).body(body(HttpStatus.UNAUTHORIZED,"Authentication required",Map.of()));}}
